# chi coverage theorem v3.1 numeric lockbox (R18+attack round)
# canonical: 01-math/01-theory/chi-coverage-canonical-v3.1-20260927.md
import math, json, hashlib
GAMMA = 0.5772156649015329
def ei(y):
    s = GAMMA + math.log(y); term = 1.0; k = 1
    while True:
        term = term*y/k; add = term/k; s += add
        if abs(add) < 1e-14 and k > 20: break
        k += 1
        if k > 500: break
    return s
def li(x): return ei(math.log(x))
LI2 = li(2.0)
def chi(x): return li(x) - LI2
def sieve(n):
    isp=[True]*(n+1); isp[0]=isp[1]=False
    for i in range(2,int(n**0.5)+1):
        if isp[i]:
            for j in range(i*i,n+1,i): isp[j]=False
    return isp
N_MAX = 20000
isp = sieve(N_MAX); primes=[i for i in range(2,N_MAX+1) if isp[i]]
anchors = {100: li(100), 10: li(10)}
assert abs(anchors[100]-30.1261)<5e-4 and abs(anchors[10]-6.1656)<5e-4
res = {'anchors': anchors, 'LI2': LI2}
nocov=[]
for N in range(6, N_MAX+1, 2):
    best=-1e18
    for p in primes:
        if p>N//2: break
        q=N-p
        if isp[q]:
            r=chi(p)+chi(q)-chi(N)
            if r>best: best=r
    if best<0: nocov.append((N,round(best,5)))
res['nocover_points']=nocov
res['domain_edge_N4']={'rho_2_2': round(2*chi(2)-chi(4),5)}
viol4=[]
for N in range(18, N_MAX+1, 2):
    for p in primes:
        if p>N//2: break
        q=N-p
        if isp[q] and chi(p)+chi(q)-chi(N)<0: viol4.append((N,p))
res['T4_violations_N_ge18']=viol4
chk=0; v2=0; tight=(1e9,None)
for N in range(12, N_MAX+1, 2):
    for p in primes:
        if p*p+p>N: break
        q=N-p
        if isp[q]:
            chk+=1
            r=chi(p)+chi(q)-chi(N); lb=chi(p)-p/(2*math.log(p))
            if r<lb: v2+=1
            if r-lb<tight[0]: tight=(r-lb,(N,p,q))
res['T2']={'checked':chk,'violations':v2,'tightest':round(tight[0],6),'at':tight[1]}
ex={}
for N in range(6,17,2):
    ex[str(N)]=[(p,round(chi(p)+chi(N-p)-chi(N),5)) for p in primes if p<=N//2 and isp[N-p]]
res['exception_table']=ex
res['T6']={str(N):{'closed_exact':round(chi(3)-(chi(N)-chi(N-3)),5),'approx':round(3/math.log(N),5)} for N in (1000,20000) if isp[N-3]}
print(json.dumps(res))
